-- PeerUP curriculum schema extension for Nigerian SSS curriculum levels.
-- Extends the existing curriculum model; does not create a parallel curriculum system.
-- Adds class_level to subjects so SSS1/SSS2/SSS3 can coexist cleanly.

BEGIN;

ALTER TABLE subjects
    ADD COLUMN IF NOT EXISTS class_level VARCHAR(20) NOT NULL DEFAULT 'ALL';

-- Existing installations may have globally-unique name/slug constraints.
-- The same subject (e.g. Physics) must be allowed once per class level.
DO $$
DECLARE
    c RECORD;
BEGIN
    FOR c IN
        SELECT conname
        FROM pg_constraint
        WHERE conrelid = 'subjects'::regclass
          AND contype = 'u'
          AND pg_get_constraintdef(oid) IN ('UNIQUE (name)', 'UNIQUE (slug)')
    LOOP
        EXECUTE format('ALTER TABLE subjects DROP CONSTRAINT IF EXISTS %I', c.conname);
    END LOOP;
END $$;

CREATE UNIQUE INDEX IF NOT EXISTS uq_subject_class_level_name
    ON subjects (class_level, name);

CREATE UNIQUE INDEX IF NOT EXISTS uq_subject_class_level_slug
    ON subjects (class_level, slug);

CREATE INDEX IF NOT EXISTS idx_subjects_class_level_active
    ON subjects (class_level, is_active);

-- Make the existing curriculum hierarchy idempotent for seed/import tooling.
CREATE UNIQUE INDEX IF NOT EXISTS uq_concept_topic_name
    ON concepts (topic_id, name);

CREATE UNIQUE INDEX IF NOT EXISTS uq_learning_objective_topic_title
    ON learning_objectives (topic_id, title);

COMMIT;
